# Domain and grid parameters
Lx, Ly, Lz = 1.0, 1.0, 0.1
nx, ny, nz = 20, 20, 1
dx, dy, dz = Lx / nx, Ly / ny, Lz / nz

# Physical parameters
h_init = 0.07
momentum_mag = 0.001
U_init = momentum_mag / h_init  # velocity from momentum h*U = 0.001

# Bump parameters
bump_height = 0.02
bump_x_start, bump_x_end = 0.4, 0.6
bump_y_start, bump_y_end = 0.4, 0.6

# Generate bed elevation values (non-uniform) for 20x20x1 grid
# Cell ordering: cell_id = i + j*nx (i varies fastest)
z_values = []
for j in range(ny):
    for i in range(nx):
        x_c = (i + 0.5) * dx
        y_c = (j + 0.5) * dy
        if (bump_x_start <= x_c <= bump_x_end and
                bump_y_start <= y_c <= bump_y_end):
            z_values.append(bump_height)
        else:
            z_values.append(0.0)

